-- ROLLBACK for 20261118120000_booking_engine.sql (generated by scripts/gen-engine-rollback.mts).
-- Restores every function the engine replaced (definition and EXECUTE rights),
-- drops the engine's functions, tables and columns. Run in one transaction:
--   psql "$DB_URL" -v ON_ERROR_STOP=1 -1 -f supabase/rollbacks/20261118120000_booking_engine.down.sql
-- then delete the migration's row from supabase_migrations.schema_migrations.
--
-- DATA: holds, guest access tokens, booking requests and payment intents are
-- dropped; per-booking price breakdowns and payment options are dropped.
-- Refuses to run while any reservation mixes room types (the previous schema
-- can't represent it), or any online payment exists.

do $$
begin
  if exists (select 1 from public.booking_rooms br join public.bookings b on b.id = br.booking_id
             where br.room_type_id <> b.room_type_id) then
    raise exception 'rollback: some reservations mix room types; change them to one type first';
  end if;
  if exists (select 1 from public.payments where method = 'online') then
    raise exception 'rollback: online payments exist; they would lose their method';
  end if;
end;
$$;

do $$
begin
  perform cron.unschedule('bsq-booking-expiry');
exception when others then
  null;  -- pg_cron absent or job not scheduled
end;
$$;

/* ---------- functions restored to their previous definitions ---------- */

CREATE OR REPLACE FUNCTION public._free_units(p_type uuid, p_in date, p_out date, p_exclude uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select (select count(*) from rooms r
          where r.room_type_id = p_type and not r.out_of_service
            and not exists (select 1 from room_blocks k
                            where k.room_id = r.id and k.released_at is null
                              and k.starts_on < p_out and k.ends_on > p_in))::integer
       - coalesce((
           select sum(b.rooms) from bookings b
           where b.room_type_id = p_type
             and b.status in ('pending', 'confirmed', 'checked_in')
             and b.check_in < p_out and b.check_out > p_in
             and (p_exclude is null or b.id <> p_exclude)
         ), 0)::integer;
$function$;

CREATE OR REPLACE FUNCTION public._insert_booking(p_room_slug text, p_check_in date, p_check_out date, p_rooms integer, p_adults integer, p_children integer, p_guest_name text, p_email text, p_phone text, p_country text, p_arrival_window text, p_special_requests text, p_airport_pickup boolean, p_source text, p_status text, p_internal_notes text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_room   room_types%rowtype;
  v_nights integer := p_check_out - p_check_in;
  v_unit   integer;
  v_ref    text;
  v_id     uuid;
begin
  if p_check_in < (now() at time zone 'Asia/Dhaka')::date then
    raise exception 'PAST_DATE';
  end if;
  if v_nights < 1 or v_nights > 30 then
    raise exception 'BAD_DATES';
  end if;
  if p_rooms is null or p_rooms < 1 or p_rooms > 5 then
    raise exception 'TOO_MANY_GUESTS';
  end if;

  select * into v_room from room_types where slug = p_room_slug for update;
  if not found or (p_source = 'website' and not v_room.is_published) then
    raise exception 'NO_ROOM';
  end if;

  -- Each room takes up to `sleeps` adults plus one child.
  if p_adults < 1 or p_children < 0
     or p_adults > v_room.sleeps * p_rooms
     or p_adults + p_children > (v_room.sleeps + 1) * p_rooms then
    raise exception 'TOO_MANY_GUESTS';
  end if;

  if public._free_units(v_room.id, p_check_in, p_check_out, null) < p_rooms then
    raise exception 'SOLD_OUT';
  end if;

  v_unit := public._stay_total(v_room.id, p_check_in, p_check_out);

  loop
    v_ref := 'BSQ-' || lpad((floor(random() * 100000))::text, 5, '0');
    exit when not exists (select 1 from bookings where reference = v_ref);
  end loop;

  insert into bookings (
    reference, room_type_id, rooms, check_in, check_out, adults, children,
    guest_name, email, phone, country, arrival_window, special_requests,
    internal_notes, airport_pickup, source, status, confirmed_at,
    nightly_rate_bdt, total_bdt
  ) values (
    v_ref, v_room.id, p_rooms, p_check_in, p_check_out, p_adults, coalesce(p_children, 0),
    trim(p_guest_name), nullif(lower(trim(coalesce(p_email, ''))), ''), trim(p_phone),
    nullif(trim(coalesce(p_country, '')), ''), nullif(trim(coalesce(p_arrival_window, '')), ''),
    nullif(trim(coalesce(p_special_requests, '')), ''), nullif(trim(coalesce(p_internal_notes, '')), ''),
    coalesce(p_airport_pickup, false), p_source, p_status,
    case when p_status = 'confirmed' then now() end,
    round(v_unit::numeric / v_nights)::integer, v_unit * p_rooms
  )
  returning id into v_id;

  perform public._log(v_id, 'created', jsonb_build_object('source', p_source, 'status', p_status));
  return v_ref;
end;
$function$;

CREATE OR REPLACE FUNCTION public._stay_total(p_type uuid, p_in date, p_out date)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(sum(
           case when public._is_weekend_night(d::date) and rt.weekend_price_bdt is not null
                then rt.weekend_price_bdt else rt.price_bdt end
         ), 0)::integer
  from room_types rt
  cross join generate_series(p_in, p_out - 1, interval '1 day') as d
  where rt.id = p_type;
$function$;

CREATE OR REPLACE FUNCTION public._sync_booking_children()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_live boolean := new.status in ('pending', 'confirmed', 'checked_in');
  v_have integer;
begin
  if tg_op = 'INSERT' then
    insert into booking_rooms (booking_id, room_type_id, room_id, check_in, check_out, active)
    select new.id, new.room_type_id, case when g = 1 then new.room_id end, new.check_in, new.check_out, v_live
    from generate_series(1, new.rooms) g;
    insert into booking_guests (booking_id, guest_id, full_name, is_primary)
    values (new.id, new.guest_id, new.guest_name, true);
    return new;
  end if;

  update booking_rooms set
    room_type_id = new.room_type_id, check_in = new.check_in, check_out = new.check_out, active = v_live
  where booking_id = new.id;

  select count(*) into v_have from booking_rooms where booking_id = new.id;
  if v_have < new.rooms then
    insert into booking_rooms (booking_id, room_type_id, check_in, check_out, active)
    select new.id, new.room_type_id, new.check_in, new.check_out, v_live from generate_series(1, new.rooms - v_have);
  elsif v_have > new.rooms then
    delete from booking_rooms where id in (
      select id from booking_rooms where booking_id = new.id order by (room_id is not null), created_at desc limit v_have - new.rooms);
  end if;

  if new.rooms = 1 and new.room_id is distinct from old.room_id then
    update booking_rooms set room_id = new.room_id where booking_id = new.id;
  end if;

  if new.guest_name is distinct from old.guest_name or new.guest_id is distinct from old.guest_id then
    update booking_guests set full_name = new.guest_name, guest_id = new.guest_id where booking_id = new.id and is_primary;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public._type_still_fits(p_type uuid, p_fewer integer)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with today as (select (now() at time zone 'Asia/Dhaka')::date as d),
  last_night as (
    select max(b.check_out) - 1 as d from bookings b
    where b.room_type_id = p_type and b.status in ('pending', 'confirmed', 'checked_in')
  )
  select not exists (
    select 1
    from generate_series((select d from today), coalesce((select d from last_night), (select d from today) - 1), interval '1 day') as n
    where public._free_units(p_type, n::date, n::date + 1, null) - p_fewer < 0
  );
$function$;

CREATE OR REPLACE FUNCTION public.admin_assign_room(p_booking uuid, p_room uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  b bookings%rowtype;
  r rooms%rowtype;
begin
  perform public._require('bookings.write');
  select * into b from bookings where id = p_booking for update;
  if not found then
    raise exception 'NOT_FOUND';
  end if;
  if b.status not in ('pending', 'confirmed', 'checked_in') or b.rooms <> 1 then
    raise exception 'LOCKED';
  end if;

  if p_room is not null then
    select * into r from rooms where id = p_room;
    if not found then
      raise exception 'NOT_FOUND';
    end if;
    if r.room_type_id <> b.room_type_id then
      raise exception 'WRONG_ROOM_TYPE';
    end if;
    if r.out_of_service then
      raise exception 'ROOM_OUT_OF_SERVICE';
    end if;
  end if;

  begin
    update bookings set room_id = p_room where id = b.id;
  exception when exclusion_violation then
    raise exception 'ROOM_TAKEN';
  end;

  perform public._log(b.id, 'room', jsonb_build_object(
    'from', (select number from rooms where id = b.room_id),
    'to', r.number
  ));
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_create_booking(p_room_slug text, p_check_in date, p_check_out date, p_rooms integer, p_adults integer, p_children integer, p_guest_name text, p_email text, p_phone text, p_country text, p_special_requests text, p_internal_notes text, p_airport_pickup boolean, p_source text, p_status text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public._require('bookings.write');
  if p_source not in ('phone', 'walk_in', 'other') or p_status not in ('pending', 'confirmed') then
    raise exception 'BAD_TRANSITION';
  end if;
  return public._insert_booking(
    p_room_slug, p_check_in, p_check_out, p_rooms, p_adults, p_children,
    p_guest_name, p_email, p_phone, p_country, null, p_special_requests,
    p_airport_pickup, p_source, p_status, p_internal_notes
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_modify_booking(p_booking uuid, p_room_slug text, p_check_in date, p_check_out date, p_rooms integer, p_adults integer, p_children integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  b        bookings%rowtype;
  v_type   room_types%rowtype;
  v_nights integer := p_check_out - p_check_in;
  v_keep   boolean;
  v_unit   integer;
  v_rate   integer;
  v_total  integer;
  v_room   uuid;
begin
  perform public._require('bookings.write');
  select * into b from bookings where id = p_booking for update;
  if not found then
    raise exception 'NOT_FOUND';
  end if;
  if b.status not in ('pending', 'confirmed', 'checked_in') then
    raise exception 'LOCKED';
  end if;
  -- Once a guest is in, only the departure date (and party) can change.
  if b.status = 'checked_in' and (p_check_in <> b.check_in or p_room_slug <> (select slug from room_types where id = b.room_type_id)) then
    raise exception 'LOCKED';
  end if;
  if v_nights < 1 or v_nights > 30 then
    raise exception 'BAD_DATES';
  end if;
  if b.status <> 'checked_in' and p_check_in < (now() at time zone 'Asia/Dhaka')::date and p_check_in <> b.check_in then
    raise exception 'PAST_DATE';
  end if;

  select * into v_type from room_types where slug = p_room_slug for update;
  if not found then
    raise exception 'NO_ROOM';
  end if;
  if p_rooms < 1 or p_rooms > 5 or p_adults < 1 or p_children < 0
     or p_adults > v_type.sleeps * p_rooms
     or p_adults + p_children > (v_type.sleeps + 1) * p_rooms then
    raise exception 'TOO_MANY_GUESTS';
  end if;
  if public._free_units(v_type.id, p_check_in, p_check_out, b.id) < p_rooms then
    raise exception 'SOLD_OUT';
  end if;

  v_keep := v_type.id = b.room_type_id and p_check_in = b.check_in and p_check_out = b.check_out;
  if v_keep then
    v_rate := b.nightly_rate_bdt;
    v_total := round(b.total_bdt::numeric / b.rooms * p_rooms)::integer;
  else
    v_unit := public._stay_total(v_type.id, p_check_in, p_check_out);
    v_rate := round(v_unit::numeric / v_nights)::integer;
    v_total := v_unit * p_rooms;
  end if;
  -- A different type or several rooms can't keep the assigned unit.
  v_room := case when v_type.id = b.room_type_id and p_rooms = 1 then b.room_id end;

  begin
    update bookings set
      room_type_id = v_type.id,
      room_id = v_room,
      check_in = p_check_in,
      check_out = p_check_out,
      rooms = p_rooms,
      adults = p_adults,
      children = p_children,
      nightly_rate_bdt = v_rate,
      total_bdt = v_total,
      payment_status = case
        when amount_paid_bdt = 0 then 'unpaid'
        when amount_paid_bdt >= v_total then 'paid'
        else 'partial' end
    where id = b.id;
  exception when exclusion_violation then
    raise exception 'ROOM_TAKEN';
  end;

  perform public._log(b.id, 'modified', jsonb_build_object(
    'from', jsonb_build_object('check_in', b.check_in, 'check_out', b.check_out, 'rooms', b.rooms,
                               'adults', b.adults, 'children', b.children, 'total', b.total_bdt),
    'to', jsonb_build_object('check_in', p_check_in, 'check_out', p_check_out, 'rooms', p_rooms,
                             'adults', p_adults, 'children', p_children, 'room_type', p_room_slug,
                             'total', v_total)
  ));
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_set_status(p_booking uuid, p_status text, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  b bookings%rowtype;
  v_today date := (now() at time zone 'Asia/Dhaka')::date;
begin
  perform public._require('bookings.write');
  select * into b from bookings where id = p_booking for update;
  if not found then
    raise exception 'NOT_FOUND';
  end if;

  if not (
    (b.status = 'pending' and p_status in ('confirmed', 'cancelled')) or
    (b.status = 'confirmed' and p_status in ('checked_in', 'cancelled', 'no_show')) or
    (b.status = 'checked_in' and p_status = 'checked_out')
  ) then
    raise exception 'BAD_TRANSITION';
  end if;

  if p_status = 'checked_in' then
    if b.check_in > v_today then
      raise exception 'TOO_EARLY';
    end if;
    if b.rooms = 1 and b.room_id is null then
      raise exception 'ASSIGN_ROOM';
    end if;
  end if;
  if p_status = 'no_show' and b.check_in > v_today then
    raise exception 'TOO_EARLY';
  end if;

  update bookings set
    status = p_status,
    cancel_reason = case when p_status in ('cancelled', 'no_show') then nullif(trim(coalesce(p_reason, '')), '') else cancel_reason end,
    confirmed_at = case when p_status = 'confirmed' then now() else confirmed_at end,
    checked_in_at = case when p_status = 'checked_in' then now() else checked_in_at end,
    checked_out_at = case when p_status = 'checked_out' then now() else checked_out_at end,
    cancelled_at = case when p_status in ('cancelled', 'no_show') then now() else cancelled_at end
  where id = b.id;

  -- A departed room needs cleaning before the next guest.
  if p_status = 'checked_out' and b.room_id is not null then
    update rooms set housekeeping = 'dirty' where id = b.room_id;
  end if;

  perform public._log(b.id, 'status', jsonb_build_object('from', b.status, 'to', p_status, 'reason', p_reason));
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_booking(p_room_slug text, p_check_in date, p_check_out date, p_rooms integer, p_adults integer, p_children integer, p_guest_name text, p_email text, p_phone text, p_country text, p_arrival_window text, p_special_requests text, p_airport_pickup boolean)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_email is null or p_email !~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    raise exception 'BAD_EMAIL';
  end if;
  -- Throttle repeated submissions for the same contact details.
  if (select count(*) from bookings
      where created_at > now() - interval '1 hour'
        and source = 'website'
        and (phone = trim(p_phone) or lower(email) = lower(trim(p_email)))) >= 3 then
    raise exception 'RATE_LIMITED';
  end if;

  return public._insert_booking(
    p_room_slug, p_check_in, p_check_out, p_rooms, p_adults, p_children,
    p_guest_name, p_email, p_phone, p_country, p_arrival_window,
    p_special_requests, p_airport_pickup, 'website', 'pending', null
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.guard_room_service()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is not null then
    if (new.number is distinct from old.number or new.room_type_id is distinct from old.room_type_id)
       and not public.has_permission('rooms.manage') then
      raise exception 'NOT_ALLOWED';
    end if;
    if new.out_of_service is distinct from old.out_of_service and not public.has_permission('maintenance.manage') then
      raise exception 'NOT_ALLOWED';
    end if;
    if new.housekeeping is distinct from old.housekeeping and not public.has_permission('housekeeping.write') then
      raise exception 'NOT_ALLOWED';
    end if;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.room_availability(p_check_in date, p_check_out date)
 RETURNS TABLE(slug text, available integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select rt.slug, greatest(0, public._free_units(rt.id, p_check_in, p_check_out, null))
  from room_types rt
  where rt.is_published;
$function$;

